        },
        "code": {
          "text": "Occupational stress and shift-work related issues"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Patient-reported history of low iron"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Fatigue"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Increased tiredness for approximately 3–4 months, most days; worse after late or long shifts, especially nights. Often needs to lie down after work. Still working full time; gym frequency decreased from 4 times per week to 1–2 times per week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Sleep duration and sleep difficulty"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Sleeps 5–6 hours on work nights and 7–8 hours on days off. Trouble winding down after night shifts and uses phone in bed."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Snoring or witnessed apnoeas"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No known snoring or apnoeas; patient lives alone."
      }
    },
